body {
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
  background: var(--dark-f8f9fb, var(--appsmith-theme-backgroundColor, #1E293A));
  margin: 0;
}

.address-container {
  display: flex;
  gap: 40px;
  background: var(--dark-ffffff, var(--appsmith-theme-surfaceColor, #0f172a));
  border-radius: 8px;
  padding: 20px 24px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.06);
  animation: slideDown 0.5s ease;
}

.address-column {
  flex: 1;
}

.address-title {
  color: var(--dark-002050, var(--appsmith-theme-textStrongColor, #ffffff));
  font-weight: 700;
  font-size: 15px;
  margin-bottom: 10px;
}

.address-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 12px;
  border-radius: 4px;
  animation: fadeIn 0.4s ease;
}

/* Alternate row background */
.address-row:nth-child(odd) {
  background: var(--dark-ffffff, var(--appsmith-theme-surfaceColor, #0f172a)); /* light gray */
}

.address-row:nth-child(even) {
  background: var(--dark-f5f5f5, var(--appsmith-theme-surfaceAltColor, #1e293b)); /* white */
}

.label {
  color: var(--dark-222222, var(--appsmith-theme-textStrongColor, #ffffff));
  font-weight: 500;
}

.value {
  font-weight: 700;
  color: var(--dark-0a0a0a, var(--appsmith-theme-textStrongColor, #ffffff));
}

